const { withDangerousMod } = require('@expo/config-plugins');
const fs = require('fs');
const path = require('path');

/**
 * The Alarm sound setting in Settings offers "Chime" and "Classic" alongside
 * "Default" (see src/screens/SettingsScreen.tsx ALARM_SOUND_OPTIONS), but on
 * Android a channel's `sound` key only works if a matching resource exists
 * at android/app/src/main/res/raw/<key>.<ext> --- notifee just passes the
 * key straight through to NotificationChannel, it doesn't bundle anything
 * itself. Like android/ as a whole, res/raw/ is fully regenerated by every
 * `expo prebuild` (clean or not), so the two tracked WAV files at
 * assets/sounds/chime.wav and assets/sounds/classic.wav need to be copied
 * into res/raw/ on every prebuild, not just committed once.
 *
 * Before this plugin existed, picking "Chime" or "Classic" silently fell
 * back to no sound at all, because the resource Android looked up never
 * existed in the generated project.
 */
module.exports = function withAlarmSoundFiles(config) {
  return withDangerousMod(config, [
    'android',
    (config) => {
      const projectRoot = config.modRequest.projectRoot;
      const destDir = path.join(config.modRequest.platformProjectRoot, 'app', 'src', 'main', 'res', 'raw');
      fs.mkdirSync(destDir, { recursive: true });

      const sounds = ['chime', 'classic'];
      for (const name of sounds) {
        const source = path.join(projectRoot, 'assets', 'sounds', `${name}.wav`);
        if (!fs.existsSync(source)) {
          throw new Error(
            `withAlarmSoundFiles: expected a bundled sound at ${source} but it's missing. ` +
              `Without it, the "${name}" alarm sound option in Settings will silently fall back to no sound.`
          );
        }
        fs.copyFileSync(source, path.join(destDir, `${name}.wav`));
      }

      return config;
    },
  ]);
};
